={{ (() => {
const messages = $('Delete_Buffer_Data').item.json.message.map(item => JSON.parse(item));

const normalizeText = (value) =>
  String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const tokenOverlapRatio = (a, b) => {
  const aTokens = Array.from(new Set(normalizeText(a).split(' ').filter(Boolean)));
  const bTokens = Array.from(new Set(normalizeText(b).split(' ').filter(Boolean)));
  if (!aTokens.length || !bTokens.length) return 0;
  const small = aTokens.length <= bTokens.length ? aTokens : bTokens;
  const largeSet = new Set(aTokens.length <= bTokens.length ? bTokens : aTokens);
  const matches = small.filter(token => largeSet.has(token)).length;
  return matches / small.length;
};

const areNearDuplicateUserTurns = (left, right) => {
  const leftText = String(left?.content_text || '').trim();
  const rightText = String(right?.content_text || '').trim();
  if (!leftText || !rightText) return false;

  const leftNorm = normalizeText(leftText);
  const rightNorm = normalizeText(rightText);
  if (!leftNorm || !rightNorm) return false;

  const leftTime = Date.parse(left?.date_time || 0);
  const rightTime = Date.parse(right?.date_time || 0);
  const diffMs = Number.isFinite(leftTime) && Number.isFinite(rightTime)
    ? Math.abs(rightTime - leftTime)
    : 0;

  const directContainment = leftNorm.includes(rightNorm) || rightNorm.includes(leftNorm);
  const overlap = tokenOverlapRatio(leftNorm, rightNorm);

  return diffMs <= 45000 && (directContainment || overlap >= 0.85);
};

const consolidated = [];
for (const message of messages) {
  const current = {
    ...message,
    content_text: String(message.content_text || '').trim(),
  };

  if (!consolidated.length) {
    consolidated.push(current);
    continue;
  }

  const previous = consolidated[consolidated.length - 1];
  if (areNearDuplicateUserTurns(previous, current)) {
    const previousLen = previous.content_text.length;
    const currentLen = current.content_text.length;
    consolidated[consolidated.length - 1] = currentLen >= previousLen
      ? { ...previous, ...current }
      : { ...current, ...previous, content_text: previous.content_text };
    continue;
  }

  consolidated.push(current);
}

const latest = consolidated[consolidated.length - 1] || {};
const joined = consolidated.map(item => item.content_text).filter(Boolean).join(' ');
const turnGoal = latest.session_state?.turn_goal ? `PREGUNTA_ACTUAL_DEL_CLIENTE: ${latest.session_state.turn_goal}\n` : '';
const stateSummary = latest.session_state_summary ? `DATOS_CONFIRMADOS_DE_LA_SESION: ${latest.session_state_summary}\n` : '';
const progressSummary = latest.conversation_progress_summary ? `ESTADO_DE_AVANCE_CONVERSACIONAL: ${latest.conversation_progress_summary}\n` : '';
const technicalPending = latest.session_state?.technical_slot_pending ? `DATO_TECNICO_PENDIENTE: ${latest.session_state.technical_slot_pending}\n` : '';
return `${turnGoal}${stateSummary}${progressSummary}${technicalPending}\nMENSAJES_RECIENTES_DEL_CLIENTE: ${joined}`.trim();
})() }}

parameters.jsCode:
// Obtener el mensaje principal
const message = items[0].json.body;

// Texto del mensaje
const content = message.content || "";

// Adjuntos
const attachments = message.attachments || [];

// Regex → generar URL interna
function makeInternal(url) {
  if (!url) return url;

  return url.replace(
    /^https:\/\/([a-zA-Z0-9\-]+)\.ocm\.aigentss\.cloud/,
    'http://$1.ocm.aigentss.cloud:3000'
  );
}

// ------------------------------------
// Procesar TODOS los attachments
// ------------------------------------
const processedAttachments = attachments.map(att => ({
  ...att,
  data_url_external: att.data_url || null,
  data_url_internal: makeInternal(att.data_url),
  thumb_url_external: att.thumb_url || null,
  thumb_url_internal: makeInternal(att.thumb_url)
}));

// ------------------------------------
// Detectar tipos presentes en el mensaje
// ------------------------------------
let type = "unknown";

// Caso: solo texto
if (attachments.length === 0 && content.trim() !== "") {
  type = "text";

// Caso: hay adjuntos
} else if (attachments.length > 0) {

  // Si TODOS son imágenes
  if (attachments.every(a => a.file_type === "image")) {
    type = content.trim() !== "" ? "image_with_text" : "image";
  }

  // Si TODOS son audios
  else if (attachments.every(a => a.file_type === "audio")) {
    type = "audio";

  // Si TODOS son location
  } else if (attachments.every(a => a.file_type === "location")) {
    type = "location";

  // Mezcla de adjuntos → híbrido
  } else {
    type = "mixed";
  }
}

return [
  {
    json: {
      type,
      content_text: content,
      attachments: processedAttachments,
      raw: items[0].json
    }
  }
];

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

// Extraer coordenadas del attachment
const attachment = node.attachments?.[0] || {};
const lat = attachment.coordinates_lat || null;
const lon = attachment.coordinates_long || null;

// Construir el content_text para el siguiente nodo
//const content = {
//  lat,
//  lon
//};
const content = `${lat}, ${lon}`;

let result = {
  type: node.type,
  content: content,   // aquí va listo para el agente
  raw: editFields
};

return [{ json: result }];

const out = [];

for (const item of $input.all()) {
  const type = item.json.type;

  if (type === "text" || type === "image_with_text") {
    out.push({
      json: {
        content: item.json.content_text,
        type: "text"
      }
    });
  } else {
    out.push(item);
  }
}

return out;

const node = items[0].json;
const editFields = $('Edit Fields').item.json;
const staticData = $getWorkflowStaticData('global');
const sessionId = String(editFields.sessionId ?? '');
const stateKey = `session_state:${sessionId}`;
const previousState = staticData[stateKey] || {};

const text = String(node.content || '').trim();

const normalizeText = (value) =>
  String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

const lowered = normalizeText(text);

const titleCase = (value) =>
  value
    .split(/\s+/)
    .filter(Boolean)
    .map(part => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase())
    .join(' ');

const extractName = (input) => {
  const patterns = [
    /me llamo\s+([a-záéíóúñ]+(?:\s+[a-záéíóúñ]+){0,2})/i,
    /soy\s+([a-záéíóúñ]+(?:\s+[a-záéíóúñ]+){0,2})/i,
    /mi nombre es\s+([a-záéíóúñ]+(?:\s+[a-záéíóúñ]+){0,2})/i,
  ];

  for (const pattern of patterns) {
    const match = input.match(pattern);
    if (match?.[1]) {
      const candidate = match[1].trim();
      const blocked = [
        'un suv',
        'de quito',
        'economico',
        'económico',
        'una bateria',
        'una batería',
      ];
      if (!blocked.includes(candidate.toLowerCase())) {
        return titleCase(candidate);
      }
    }
  }
  return null;
};


const extractStandaloneName = (input) => {
  const value = String(input || '').trim();
  const normalized = normalizeText(value);
  const words = value.split(/\s+/).filter(Boolean);

  if (!value || value.length > 60) return null;
  if (words.length < 2 || words.length > 4) return null;
  if (/[^a-zA-ZáéíóúÁÉÍÓÚñÑüÜ\s'-]/.test(value)) return null;
  if (/[?¿!¡.,:;\/\\0-9]/.test(value)) return null;

  const blockedTerms = [
    'hola', 'buenos', 'buenas', 'dias', 'tardes', 'noches', 'gracias',
    'quito', 'guayaquil', 'cuenca', 'manta', 'ambato', 'machala', 'loja',
    'local', 'locales', 'sucursal', 'sucursales', 'agencia', 'agencias',
    'direccion', 'direcciones', 'ubicacion', 'ubicaciones', 'horario', 'horarios',
    'llanta', 'llantas', 'bateria', 'baterias', 'aceite', 'mantenimiento',
    'freno', 'frenos', 'alineacion', 'balanceo', 'precio', 'precios', 'promo',
    'promocion', 'promociones', 'rin', 'suv', 'auto', 'carro', 'vehiculo',
    'quiero', 'necesito', 'busco', 'cotizar', 'cotizacion', 'asesor', 'asesoria', 'concesionario', 'concesionarios', 'concecionartios', 'concecionarios', 'tienes'
  ];

  const normalizedWords = normalized.split(/\s+/).filter(Boolean);
  const blockedStartTerms = ['en', 'que', 'cual', 'cuales', 'donde', 'quiero', 'necesito', 'busco', 'tengo'];
  if (blockedStartTerms.includes(normalizedWords[0])) return null;
  if (normalizedWords.some(word => blockedTerms.includes(word))) return null;

  return titleCase(value);
};

const extractCity = (input) => {
  if (/\bquito\b/i.test(input)) return 'Quito';
  if (/\bguayaquil\b/i.test(input)) return 'Guayaquil';
  if (/cumbaya|cumbay[aá]/i.test(input)) return 'Cumbaya';
  return null;
};

const extractBranch = (input) => {
  const normalized = normalizeText(input);
  if (/monteserr|montecerr|monte\s*s?err|monte\s*cerr/i.test(normalized)) return 'Monteserrin';
  if (/\bbrasil\b/i.test(normalized)) return 'Brasil';
  if (/eloy\s+alfaro/i.test(normalized) || /higueras/i.test(normalized)) return 'Eloy Alfaro';
  if (/guayaquil/i.test(normalized)) return 'Guayaquil';
  return null;
};

const extractService = (input) => {
  if (/bater/i.test(input)) return 'bateria';
  if (/llanta|neumatico|\brin\b|\brin\s*\d{2}\b|\baro\b|\baro\s*\d{2}\b/i.test(normalizeText(input))) return 'llantas';
  if (/aceite/i.test(input)) return 'cambio de aceite';
  if (/mantenimiento/i.test(input)) return 'mantenimiento';
  if (/freno/i.test(input)) return 'frenos';
  if (/alinea|balance/i.test(input)) return 'alineacion y balanceo';
  if (/suspensi/i.test(input)) return 'suspension';
  if (/diagnostico|escan/i.test(normalizeText(input))) return 'diagnostico';
  return null;
};

const extractNeed = (input) => {
  if (/garant/i.test(input)) return 'garantia';
  if (/sabado|horario|atienden|atienden hoy|atienden hoy\?/i.test(normalizeText(input))) return 'horario';
  if (/sucursal|agencia|donde|ubicaci/i.test(normalizeText(input))) return 'sucursal';
  if (/precio|cuanto|cotiz/i.test(normalizeText(input))) return 'cotizacion';
  if (/econom/i.test(normalizeText(input))) return 'economico';
  return null;
};

const extractCampaignInterest = (input) => {
  const normalized = normalizeText(input);
  if (/mundial|fiesta\s+del\s+futbol|futbol|cromos|album|mantenimiento\s+preventivo|abc\s+de\s+frenos|abc\s+de\s+motor/i.test(normalized)) {
    return 'mundial_mantenimiento';
  }
  if (/3\s*x\s*4|3x4|cuarta\s+gratis|promo(?:cion)?\s+.*llantas|llantas\s+.*promo(?:cion)?/i.test(normalized)) {
    return 'llantas_3x4';
  }
  return null;
};

const extractVehicleType = (input) => {
  if (/\bsuv\b/i.test(input)) return 'SUV';
  if (/camioneta|pickup|pick up/i.test(input)) return 'camioneta';
  if (/sedan/i.test(input)) return 'sedan';
  if (/hatchback|hatch/i.test(input)) return 'hatchback';
  if (/jeep|4x4/i.test(input)) return '4x4';
  return null;
};

const extractRimSize = (input) => {
  const patterns = [
    /\brin\s*(\d{2})\b/i,
    /\baro\s*(\d{2})\b/i,
    /\br\s?(\d{2})\b/i,
  ];

  for (const pattern of patterns) {
    const match = input.match(pattern);
    if (match?.[1]) {
      return `rin ${match[1]}`;
    }
  }
  return null;
};

const extractTireMeasure = (input) => {
  const normalized = normalizeText(input).replace(/\s+/g, ' ').trim();
  const compact = normalized.replace(/\s+/g, '');

  const direct = compact.match(/\b(\d{3}\/?\d{2}r\d{2})\b/);
  if (direct?.[1]) {
    const raw = direct[1];
    const withSlash = raw.includes('/')
      ? raw
      : raw.replace(/^(\d{3})(\d{2}r\d{2})$/, '$1/$2');
    return withSlash.toUpperCase();
  }

  const spaced = normalized.match(/\b(\d{3})\s+(\d{2})\s*r\s*(\d{2})\b/);
  if (spaced) {
    return `${spaced[1]}/${spaced[2]}R${spaced[3]}`.toUpperCase();
  }

  const slashSpaced = normalized.match(/\b(\d{3})\/(\d{2})\s*r\s*(\d{2})\b/);
  if (slashSpaced) {
    return `${slashSpaced[1]}/${slashSpaced[2]}R${slashSpaced[3]}`.toUpperCase();
  }

  return null;
};

const extractBatteryReference = (input) => {
  const patterns = [
    /\b(ns\d{2,3}[a-z]?)\b/i,
    /\b(ln\d{2,3})\b/i,
    /\b(\d{2,3}d\d{2})\b/i,
    /\bbateria\s+(\d{2,3}[a-z]?)\b/i,
    /\bbater[ií]a\s+([a-z0-9-]{2,10})\b/i,
  ];

  for (const pattern of patterns) {
    const match = input.match(pattern);
    if (match?.[1]) {
      return match[1].toUpperCase();
    }
  }
  return null;
};

const extractPriceSensitivity = (input) => {
  if (/econom/i.test(normalizeText(input))) return 'economico';
  if (/premium|mejor/i.test(normalizeText(input))) return 'premium';
  return null;
};

const inferOpenTopic = ({ service, currentNeed, previousState }) =>
  service || currentNeed || previousState.open_topic || null;

const inferTechnicalState = ({
  service,
  previousState,
  vehicleType,
  rimSize,
  tireMeasure,
  batteryReference,
}) => {
  let technicalSlotPending = previousState.technical_slot_pending || null;
  let technicalSlotValue = previousState.technical_slot_value || null;
  const previousTechnicalValue = String(previousState.technical_slot_value || '');
  const previousHasFullTireMeasure = /\b\d{3}\/\d{2}R\d{2}\b/i.test(previousTechnicalValue);
  const previousHasRimOnly = /\brin\s*\d{2}\b/i.test(previousTechnicalValue);

  if (service === 'llantas') {
    if (tireMeasure) {
      technicalSlotPending = null;
      technicalSlotValue = `medida ${tireMeasure}`;
    } else if (previousHasFullTireMeasure) {
      technicalSlotPending = null;
      technicalSlotValue = previousTechnicalValue;
    } else if (rimSize) {
      technicalSlotPending = null;
      technicalSlotValue = rimSize;
    } else if (previousHasRimOnly) {
      technicalSlotPending = null;
      technicalSlotValue = previousTechnicalValue;
    } else {
      technicalSlotPending = 'rim_size';
      technicalSlotValue = vehicleType || previousState.technical_slot_value || null;
    }
  } else if (service === 'bateria') {
    if (batteryReference) {
      technicalSlotPending = null;
      technicalSlotValue = batteryReference;
    } else if (previousState.technical_slot_value && !previousState.technical_slot_pending) {
      technicalSlotPending = null;
      technicalSlotValue = previousState.technical_slot_value;
    } else {
      technicalSlotPending = 'vehicle_model_or_battery_reference';
      technicalSlotValue = previousState.technical_slot_value || null;
    }
  } else {
    technicalSlotPending = null;
    technicalSlotValue = previousState.technical_slot_value || null;
  }

  return { technicalSlotPending, technicalSlotValue };
};

const extractTurnGoal = ({
  input,
  service,
  currentNeed,
  city,
  branch,
  technicalSlotPending,
  vehicleType,
  campaignInterest,
  previousState,
}) => {
  const normalized = normalizeText(input);
  const branchAlreadyOffered = Boolean(previousState.branches_offered);
  const hoursAlreadyAnswered = Boolean(previousState.hours_answered);
  const warrantyAlreadyAnswered = Boolean(previousState.warranty_answered);
  const technicalAlreadyAsked = Boolean(previousState.technical_slot_asked && previousState.technical_slot_pending);

  if (campaignInterest === 'mundial_mantenimiento') {
    if (branch) {
      return 'Mantener el foco en la promo Mundial 2026. Confirmar la agencia elegida y pedir solo el servicio de mantenimiento que desea realizar. No cambiar a llantas ni pedir rin o medida.';
    }
    return 'Mantener el foco en la promo Mundial 2026 de mantenimientos. Explicar o continuar esa promocion sin mezclarla con 3x4 en llantas.';
  }

  if (campaignInterest === 'llantas_3x4') {
    return 'Mantener el foco en la promocion 3x4 en llantas y pedir solo la medida o rin si aun falta.';
  }

  if (/garant/i.test(input)) {
    if (branchAlreadyOffered || hoursAlreadyAnswered) {
      return 'Responder solo la garantia solicitada en una salida compacta. No continuar listas de sucursales ni repetir horarios en este turno.';
    }
    if (warrantyAlreadyAnswered) {
      return 'Confirmar brevemente la garantia sin reabrir otras ramas de la conversacion.';
    }
    return service
      ? `Responder si ${service} tiene garantia y aclarar esa duda antes de abrir sucursales, horarios o derivacion.`
      : 'Responder la consulta de garantia antes de pedir datos adicionales.';
  }

  if (/sabado|horario|atienden/i.test(normalized)) {
    if (branchAlreadyOffered) {
      return 'Responder solo el horario solicitado en una salida compacta. No continuar ni completar listas de sucursales previas.';
    }
    if (hoursAlreadyAnswered) {
      return 'Confirmar o complementar el horario sin repetir bloques largos ni otras ramas.';
    }
    return city || branch
      ? `Responder el horario de atencion relacionado con ${service || 'el servicio consultado'} usando ${branch || city} solo como apoyo, sin mezclar otras ramas.`
      : `Responder primero el horario de atencion relacionado con ${service || 'el servicio consultado'} antes de pedir mas datos.`;
  }

  if (/sucursal|agencia|donde|ubicaci/i.test(normalized)) {
    if (branchAlreadyOffered) {
      return 'Si ya mostraste sucursales, no repitas toda la lista. Confirma la agencia adecuada o resume la recomendacion en una sola salida.';
    }
    return city
      ? `Indicar la sucursal o agencia mas conveniente en ${city} y mantener el foco en ${service || 'la necesidad actual'}.`
      : 'Indicar la sucursal mas adecuada segun el servicio y pedir solo la ciudad si sigue siendo necesaria.';
  }

  if (/precio|cuanto|cotiz/i.test(normalized)) {
    return `Orientar la cotizacion de ${service || 'la necesidad consultada'} sin inventar precios exactos y pedir un solo dato faltante si hace falta.`;
  }

  if (service === 'llantas') {
    if (technicalSlotPending === 'rim_size') {
      if (technicalAlreadyAsked) {
        return 'Ya pediste antes el rin o la medida. No repitas la misma pregunta textual. Reconoce los datos nuevos y di que solo falta ese dato tecnico para continuar.';
      }
      return vehicleType
        ? 'Mantener el foco en llantas para ese tipo de vehiculo y pedir solo el rin o medida faltante, sin volver a preguntar nombre o ciudad.'
        : 'Mantener el foco en llantas y pedir solo el rin o medida faltante, sin mezclar sucursales ni derivacion.';
    }
    return 'Mantener el foco en llantas y responder primero la necesidad actual antes de seguir calificando.';
  }

  if (service === 'bateria') {
    if (branchAlreadyOffered || hoursAlreadyAnswered || warrantyAlreadyAnswered) {
      return 'Mantener el foco en bateria y responder solo la nueva pregunta del cliente sin reabrir horarios ni sucursales ya tratadas.';
    }
    return 'Mantener el foco en bateria y responder la duda actual antes de derivar o abrir otras ramas.';
  }

  if (service) {
    return `Responder primero la consulta actual relacionada con ${service} antes de volver a calificar o derivar.`;
  }

  return previousState.turn_goal || 'Responder primero la ultima pregunta o necesidad del cliente antes de pedir datos adicionales.';
};

const detectedBranch = extractBranch(text);
const detectedCampaignInterest = extractCampaignInterest(text);
const detectedService = detectedBranch ? null : extractService(text);
const service = detectedCampaignInterest === 'mundial_mantenimiento'
  ? 'mantenimiento'
  : (detectedService || previousState.service || null);
const currentNeed = extractNeed(text) || previousState.current_need || null;
const city = extractCity(text) || previousState.city || null;
const branch = detectedBranch || previousState.branch || null;
const campaignInterest = detectedCampaignInterest || previousState.campaign_interest || null;
const customerName = extractName(text) || extractStandaloneName(text) || previousState.customer_name || null;
const vehicleType = extractVehicleType(text) || previousState.vehicle_type || null;
const priceSensitivity = extractPriceSensitivity(text) || previousState.price_sensitivity || null;
const rimSize = extractRimSize(text);
const tireMeasure = extractTireMeasure(text);
const batteryReference = extractBatteryReference(text);
const openTopic = inferOpenTopic({ service, currentNeed, previousState });
const { technicalSlotPending, technicalSlotValue } = inferTechnicalState({
  service,
  previousState,
  vehicleType,
  rimSize,
  tireMeasure,
  batteryReference,
});

const currentState = {
  ...previousState,
  sessionId,
  last_message_at: editFields['body.date_time'] || new Date().toISOString(),
  last_user_message: text,
  customer_name: customerName,
  city,
  branch,
  service,
  current_need: currentNeed,
  campaign_interest: campaignInterest,
  vehicle_type: vehicleType,
  price_sensitivity: priceSensitivity,
  open_topic: openTopic,
  technical_slot_pending: technicalSlotPending,
  technical_slot_value: technicalSlotValue,
  quote_flow_started: Boolean(previousState.quote_flow_started || currentNeed === 'cotizacion'),
  hours_answered: Boolean(previousState.hours_answered),
  warranty_answered: Boolean(previousState.warranty_answered),
  branches_offered: Boolean(previousState.branches_offered),
  technical_slot_asked: Boolean(previousState.technical_slot_asked),
  handoff_offered: Boolean(previousState.handoff_offered),
  handoff_requested: Boolean(previousState.handoff_requested || /(asesor|agente|humano|persona)/i.test(text)),
  last_answer_focus: previousState.last_answer_focus || null,
  last_qualification_prompt: previousState.last_qualification_prompt || null,
};

currentState.turn_goal = extractTurnGoal({
  input: text,
  service: currentState.service,
  currentNeed: currentState.current_need,
  city: currentState.city,
  branch: currentState.branch,
  technicalSlotPending: currentState.technical_slot_pending,
  vehicleType: currentState.vehicle_type,
