try {
  if (!candidate || candidate.length < 3) return [];

  let requester = null;
  try { requester = typeof $helpers !== 'undefined' ? $helpers.httpRequest : null; } catch (error) {}
  try { requester = requester || (this?.helpers?.httpRequest ? this.helpers.httpRequest.bind(this.helpers) : null); } catch (error) {}
  if (!requester) return [];

  const edit = safeNodeJson('Edit Fields');
  const webhook = safeNodeJson('Webhook');
  const conversation = edit.body?.conversation || webhook.body?.conversation || {};
  const message = Array.isArray(conversation.messages) ? conversation.messages[0] || {} : {};
  const sender = conversation.meta?.sender || message.sender || webhook.body?.sender || {};

  const accountId = edit.body?.account?.id || webhook.body?.account?.id || conversation.account_id || message.account_id;
  const contactId = sender.id || conversation.contact_inbox?.contact_id || message.sender_id;
  const currentName = sender.name || message.sender?.name || '';
  const baseUrl = edit.URL_OMNICEM || 'chatwoot:3000';
  const token = edit.TOKEN || '';
  const contactUpdateToken = edit.CONTACT_UPDATE_TOKEN || 'yQXLb7Nt4Amq5uhFHjoBL8Ge' || token;

